/* For Blood RANK module — mode rank: makin tinggi rank, makin sulit musuhnya.
 * Dimuat sebagai <script src="./forblood-rank.js"></script> sebelum forblood-mabar.js.
 * Hook engine (di index.html): fbRank.beginMatch / active / cfg / label / finish.
 */
(function () {
  'use strict';
  const BADGES = {"brit1":"data:image/webp;base64,","brit2":"data:image/webp;base64,","brit3":"data:image/webp;base64,","brit4":"data:image/webp;base64,","voxy1":"data:image/webp;base64,","voxy2":"data:image/webp;base64,","voxy3":"data:image/webp;base64,","voxy4":"data:image/webp;base64,","silv1":"data:image/webp;base64,","silv2":"data:image/webp;base64,","silv3":"data:image/webp;base64,","gold1":"data:image/webp;base64,","gold2":"data:image/webp;base64,","gold3":"data:image/webp;base64,","gold4":"data:image/webp;base64,","plat1":"data:image/webp;base64,","plat2":"data:image/webp;base64,","plat3":"data:image/webp;base64,","plat4":"data:image/webp;base64,","aur1":"data:image/webp;base64,","aur2":"data:image/webp;base64,","aur3":"data:image/webp;base64,","aur4":"data:image/webp;base64,","roy1":"data:image/webp;base64,","roy2":"data:image/webp;base64,","roy3":"data:image/webp;base64,","roy999":"data:image/webp;base64,"};

  // Urutan sesuai gambar "tampilan dan urutan rank di forblood next update"
  const T = (key, name, grp) => ({ key, name, grp });
  const TIERS = [
    T('brit1', 'Brittlewood I', 'Brittlewood'), T('brit2', 'Brittlewood II', 'Brittlewood'), T('brit3', 'Brittlewood III', 'Brittlewood'), T('brit4', 'Brittlewood IV', 'Brittlewood'),
    T('voxy1', 'Voxy I', 'Voxy'), T('voxy2', 'Voxy II', 'Voxy'), T('voxy3', 'Voxy III', 'Voxy'), T('voxy4', 'Voxy IV', 'Voxy'),
    T('silv1', 'Silver I', 'Silver'), T('silv2', 'Silver II', 'Silver'), T('silv3', 'Silver III', 'Silver'),
    T('gold1', 'Gold I', 'Gold'), T('gold2', 'Gold II', 'Gold'), T('gold3', 'Gold III', 'Gold'), T('gold4', 'Gold IV', 'Gold'),
    T('plat1', 'Platinum I', 'Platinum'), T('plat2', 'Platinum II', 'Platinum'), T('plat3', 'Platinum III', 'Platinum'), T('plat4', 'Platinum IV', 'Platinum'),
    T('aur1', 'Aurora I', 'Aurora'), T('aur2', 'Aurora II', 'Aurora'), T('aur3', 'Aurora III', 'Aurora'), T('aur4', 'Aurora IV', 'Aurora'),
    T('roy1', 'Royal Star ★', 'Royal Star'), T('roy2', 'Royal Star ★★', 'Royal Star'), T('roy3', 'Royal Star ★★★', 'Royal Star'),
    T('roy999', 'Royal Star 999', 'Royal Star')
  ];
  const MAXT = TIERS.length - 1;     // 26
  const PER = 100;                   // poin rank (RP) per tier
  const S = { on: false, done: false, tier: 0, res: null };

  const LS = {
    get(k) { try { return localStorage.getItem(k); } catch (_) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (_) {} }
  };
  const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt !== undefined) e.textContent = txt; return e; };

  function rp() { return Math.max(0, parseInt(LS.get('fb_rank_rp'), 10) || 0); }
  function tierOf(r) { return Math.min(MAXT, Math.floor(r / PER)); }
  function setRp(v) {
    v = Math.max(0, Math.floor(v));
    LS.set('fb_rank_rp', String(v));
    const t = tierOf(v);
    if (t > (parseInt(LS.get('fb_rank_best'), 10) || 0)) LS.set('fb_rank_best', String(t));
  }
  function mode() { return LS.get('fb_mode') === 'rank' ? 'rank' : 'classic'; }
  function setMode(m) { LS.set('fb_mode', m === 'rank' ? 'rank' : 'classic'); refreshButton(); renderPanel(); }
  function inRoom() { try { return !!(window.fbMabarInRoom && window.fbMabarInRoom()); } catch (_) { return false; } }
  function badge(t) { const k = TIERS[Math.max(0, Math.min(MAXT, t | 0))].key; return BADGES[k] || ''; }

  // ---- kesulitan: makin tinggi tier, makin sulit (0 = Brittlewood I ... 1 = Royal Star 999) ----
  function cfgFor(t) {
    const x = t / MAXT;
    return {
      tier: t,
      total: Math.round(50 + 30 * x),   // jumlah jelly 50 -> 80
      hp: 1 + 1.5 * x,                  // darah jelly  x1 -> x2.5
      spd: 1 + 0.45 * x,                // kecepatan    x1 -> x1.45
      dmg: 1 + 0.9 * x,                 // damage jelly x1 -> x1.9
      vis: 1 + 0.55 * x,                // jarak pandang jelly x1 -> x1.55
      atk: 1 - 0.35 * x,                // jeda serangan x1 -> x0.65 (lebih cepat)
      heavy: 0.10 + 0.15 * x,           // peluang jelly raksasa
      fast: 0.20 + 0.10 * x,            // peluang jelly cepat
      mid: 0.20 + 0.05 * x              // peluang jelly ungu
    };
  }
  function cfg() { return cfgFor(S.on ? S.tier : tierOf(rp())); }
  function pct(v) { return '+' + Math.round((v - 1) * 100) + '%'; }

  // ---- siklus match ----
  function beginMatch() {
    S.on = mode() === 'rank' && !inRoom();   // rank hanya untuk solo (mabar tetap klasik)
    S.done = false; S.res = null; S.tier = tierOf(rp());
  }
  function active() { return S.on && !S.done; }
  function label() { return TIERS[S.on ? S.tier : tierOf(rp())].name; }

  function finish(win, kills, total, score, forfeit) {
    if (!S.on || S.done) return '';
    S.done = true;
    const t0 = S.tier, r0 = rp();
    const prog = Math.max(0, Math.min(1, kills / Math.max(1, total)));
    let d;
    if (win) d = Math.max(14, 34 - Math.floor(t0 * 0.75));                       // menang: +34 (bawah) ... +14 (atas)
    else {
      const base = 8 + Math.floor(t0 * 0.9);                                      // kalah: -8 ... -31
      d = forfeit ? -Math.round(base * 1.1) : -Math.round(base * (1 - prog * 0.8)); // makin banyak jelly dibunuh, makin kecil penalti
    }
    const r1 = Math.max(0, r0 + d);
    setRp(r1);
    S.res = { d: r1 - r0, t0, t1: tierOf(r1), r1, win: !!win };
    refreshButton(); renderPanel();
    return resultHTML();
  }
  function resultHTML() {
    const r = S.res; if (!r) return '';
    const up = r.t1 > r.t0, down = r.t1 < r.t0;
    const col = r.d >= 0 ? '#7dff9c' : '#ff8a80';
    const sup = r.t1 === MAXT ? ' • ' + (r.r1 - MAXT * PER) + ' RP di atas Super Star' : '';
    return '<div style="margin-top:14px;display:flex;align-items:center;justify-content:center;gap:12px;font:700 15px Arial,sans-serif">' +
      '<img src="' + badge(r.t1) + '" style="height:64px;width:auto" alt="">' +
      '<div style="text-align:left"><div style="color:' + col + ';font-size:22px;font-weight:900">' + (r.d >= 0 ? '+' : '') + r.d + ' RP</div>' +
      '<div>' + TIERS[r.t1].name + (up ? ' ▲ NAIK RANK' : down ? ' ▼ TURUN RANK' : '') + sup + '</div>' +
      (r.t1 === MAXT ? '' : '<div style="opacity:.7;font-size:12px">' + (r.r1 % PER) + ' / ' + PER + ' RP di tier ini</div>') + '</div></div>';
  }

  // ---- UI ----
  let btn = null, overlay = null, body = null;
  function injectStyles() {
    if (document.getElementById('fbRankStyles')) return;
    const s = el('style'); s.id = 'fbRankStyles';
    s.textContent = `
#lobby #fbRankOpen{position:absolute;right:1.5%;left:auto;top:auto;bottom:21.5%;width:16%;height:9%;padding:0 .6vw;display:flex;align-items:center;justify-content:center;gap:.7vw;border:1px solid rgba(255,224,126,.95);border-radius:7px;background:linear-gradient(180deg,rgba(62,48,17,.96),rgba(19,16,8,.97));box-shadow:0 0 0 1px rgba(0,0,0,.75),0 0 18px rgba(244,207,69,.2);color:#ffe27a;text-shadow:0 1px 3px #000;font:900 clamp(9px,2.1vh,15px) Orbitron,Audiowide,Arial,sans-serif;letter-spacing:.06em;z-index:12;pointer-events:auto;cursor:pointer;line-height:1.15}
#lobby #fbRankOpen img{height:86%;width:auto;max-width:36%;object-fit:contain;pointer-events:none}
#lobby #fbRankOpen small{display:block;font:700 clamp(8px,1.7vh,12px) Arial,sans-serif;letter-spacing:.02em;opacity:.85;color:#fff}
#lobby #fbRankOpen:active{transform:scale(.97);filter:brightness(1.2)}
#fbRankOverlay{position:fixed;inset:0;z-index:999989;display:none;align-items:center;justify-content:center;padding:2vh 2vw;background:radial-gradient(ellipse at center,rgba(32,27,14,.94),rgba(0,0,0,.97));font-family:Audiowide,Orbitron,Arial,sans-serif;color:#fff}
#fbRankOverlay.show{display:flex}
#fbRankOverlay *{box-sizing:border-box}
#fbRkCard{width:min(980px,97vw);height:min(660px,94dvh);display:flex;flex-direction:column;gap:10px;padding:clamp(10px,1.8vw,22px);border:1px solid #9c7922;border-radius:12px;background:linear-gradient(140deg,rgba(30,28,21,.98),rgba(9,10,11,.99));box-shadow:0 18px 60px #000;overflow:hidden}
.fbRkHead{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(244,207,69,.35);padding-bottom:8px}
.fbRkTitle{font-size:clamp(16px,3vh,26px);font-weight:900;letter-spacing:.13em;color:#ffdc69}
.fbRkClose{background:#171713;border:1px solid #6c571f;border-radius:7px;color:#ffdf74;font-size:22px;width:38px;height:36px;cursor:pointer}
.fbRkBody{flex:1;min-height:0;overflow:auto;display:flex;gap:14px;-webkit-overflow-scrolling:touch}
.fbRkLeft{flex:0 0 38%;display:flex;flex-direction:column;gap:10px;align-items:center;text-align:center}
.fbRkRight{flex:1;min-width:0}
.fbRkBig{height:clamp(90px,24vh,170px);width:auto;filter:drop-shadow(0 6px 14px rgba(0,0,0,.6))}
.fbRkName{font-size:clamp(16px,3vh,24px);font-weight:900;color:#ffe27a;letter-spacing:.06em}
.fbRkBar{width:100%;height:12px;border-radius:7px;background:#14140f;border:1px solid #5b5236;overflow:hidden}
.fbRkBar i{display:block;height:100%;background:linear-gradient(90deg,#8d6a13,#ffd95a)}
.fbRkSub{font:700 12px Arial,sans-serif;opacity:.85}
.fbRkModes{display:flex;gap:8px;width:100%}
.fbRkMode{flex:1;min-height:42px;border-radius:7px;border:1px solid #645321;background:#151713;color:#ffe18a;font:900 12px Orbitron,Audiowide,Arial,sans-serif;letter-spacing:.06em;cursor:pointer}
.fbRkMode.on{background:linear-gradient(#f2d45c,#b68b1d);color:#19160d;border-color:#a07d24}
.fbRkDiff{width:100%;text-align:left;font:12px Arial,sans-serif;line-height:1.55;padding:9px 10px;border:1px solid #353126;border-radius:8px;background:rgba(255,255,255,.03)}
.fbRkDiff b{color:#f3d76d}
.fbRkGrp{font:900 11px Arial,sans-serif;letter-spacing:.12em;color:#e9ce6c;margin:10px 0 6px}
.fbRkGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:8px}
.fbRkTier{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:4px;height:112px;padding:6px 4px;border:1px solid #353126;border-radius:8px;background:rgba(255,255,255,.03);font:700 11px Arial,sans-serif;text-align:center}
.fbRkTier img{height:70px;width:auto;max-width:90%;object-fit:contain}
.fbRkTier.low img{opacity:.38;filter:grayscale(.7)}
.fbRkTier.cur{border-color:#ffd95a;background:rgba(244,207,69,.12);box-shadow:0 0 14px rgba(244,207,69,.25)}
.fbRkTier.cur:after{content:'KAMU';position:absolute;top:3px;right:4px;font:900 9px Arial,sans-serif;background:#ffd95a;color:#19160d;border-radius:3px;padding:1px 4px}
.fbRkGo{width:100%;min-height:46px;border-radius:7px;border:1px solid #a07d24;background:linear-gradient(#f2d45c,#b68b1d);color:#19160d;font:900 13px Orbitron,Audiowide,Arial,sans-serif;letter-spacing:.06em;cursor:pointer}
@media(max-width:760px){#lobby #fbRankOpen{width:19%;bottom:21.5%}.fbRkBody{flex-direction:column}.fbRkLeft{flex:0 0 auto}.fbRkTier{height:100px}.fbRkTier img{height:60px}}
`;
    document.head.appendChild(s);
  }
  function refreshButton() {
    if (!btn) return;
    const t = tierOf(rp());
    btn.replaceChildren();
    const img = el('img'); img.alt = ''; img.src = badge(t);
    const txt = el('div'); txt.style.textAlign = 'left';
    txt.append(document.createTextNode(mode() === 'rank' ? 'RANK' : 'KLASIK'));
    const sm = el('small', '', TIERS[t].name); txt.append(sm);
    btn.append(img, txt);
  }
  function build() {
    if (overlay) return;
    overlay = el('div'); overlay.id = 'fbRankOverlay';
    overlay.setAttribute('role', 'dialog'); overlay.setAttribute('aria-label', 'Mode dan Rank');
    const card = el('div'); card.id = 'fbRkCard';
    const head = el('div', 'fbRkHead');
    head.append(el('div', 'fbRkTitle', 'FOR BLOOD // RANK'));
    const x = el('button', 'fbRkClose', '×'); x.type = 'button'; x.addEventListener('click', close); head.append(x);
    body = el('div', 'fbRkBody');
    card.append(head, body); overlay.append(card); document.body.append(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && overlay.classList.contains('show')) close(); });
  }
  function renderPanel() {
    if (!body) return;
    const r = rp(), t = tierOf(r), c = cfgFor(t), m = mode();
    body.replaceChildren();
    const left = el('div', 'fbRkLeft');
    const big = el('img', 'fbRkBig'); big.src = badge(t); big.alt = '';
    left.append(big, el('div', 'fbRkName', TIERS[t].name));
    const bar = el('div', 'fbRkBar'); const fill = el('i');
    fill.style.width = (t === MAXT ? 100 : (r % PER)) + '%'; bar.append(fill);
    left.append(bar);
    left.append(el('div', 'fbRkSub', t === MAXT ? 'SUPER STAR • ' + (r - MAXT * PER) + ' RP di atas batas' : (r % PER) + ' / ' + PER + ' RP  →  ' + TIERS[t + 1].name));
    const modes = el('div', 'fbRkModes');
    const mk = (id, txt) => { const b = el('button', 'fbRkMode' + (m === id ? ' on' : ''), txt); b.type = 'button'; b.addEventListener('click', () => setMode(id)); return b; };
    modes.append(mk('classic', 'KLASIK'), mk('rank', 'RANK'));
    left.append(modes);
    const diff = el('div', 'fbRkDiff');
    diff.innerHTML = '<b>Kesulitan di rankmu</b><br>Jumlah jelly: <b>' + c.total + '</b><br>Darah jelly: <b>' + pct(c.hp) + '</b> • Kecepatan: <b>' + pct(c.spd) + '</b><br>' +
      'Damage: <b>' + pct(c.dmg) + '</b> • Jarak pandang: <b>' + pct(c.vis) + '</b><br>Serangan lebih cepat: <b>' + Math.round((1 - c.atk) * 100) + '%</b><br>' +
      '<span style="opacity:.75">Menang: +RP • Kalah/keluar: −RP. Mode rank hanya untuk main solo (mabar tetap klasik).</span>';
    left.append(diff);
    const go = el('button', 'fbRkGo', 'MAIN ' + (m === 'rank' ? 'RANK' : 'KLASIK')); go.type = 'button';
    go.addEventListener('click', () => { close(); if (typeof window.startMatchLoading === 'function') window.startMatchLoading(); });
    left.append(go);

    const right = el('div', 'fbRkRight');
    let last = '', grid = null;
    TIERS.forEach((tr, i) => {
      if (tr.grp !== last) { last = tr.grp; right.append(el('div', 'fbRkGrp', tr.grp.toUpperCase())); grid = el('div', 'fbRkGrid'); right.append(grid); }
      const cell = el('div', 'fbRkTier' + (i === t ? ' cur' : '') + (i > t ? ' low' : ''));
      const im = el('img'); im.src = badge(i); im.alt = tr.name; im.loading = 'lazy';
      cell.append(im, el('div', '', tr.name)); grid.append(cell);
    });
    body.append(left, right);
  }
  function open() { injectStyles(); build(); renderPanel(); overlay.classList.add('show'); try { window.playClick && window.playClick(); } catch (_) {} }
  function close() { if (overlay) overlay.classList.remove('show'); }

  function addButton() {
    injectStyles();
    const hud = document.getElementById('lobHud');
    if (!hud || document.getElementById('fbRankOpen')) return;
    btn = el('button'); btn.id = 'fbRankOpen'; btn.type = 'button'; btn.setAttribute('aria-label', 'Mode dan rank');
    btn.addEventListener('click', open);
    hud.append(btn); refreshButton();
  }
  window.fbRank = { tiers: TIERS, tier: () => tierOf(rp()), rp, mode, setMode, active, cfg, label, badge, beginMatch, finish, open, close, resultHTML };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', addButton, { once: true }); else addButton();
  setInterval(refreshButton, 4000); // ikut data yang tersinkron dari cloud
})();
